namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class TrainingJobFactory(string resourceName = null, Action<Humidifier.SageMaker.TrainingJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.TrainingJob>(resourceName)
{

    internal List<InnerTrainingJobChannelFactory> InputDataConfigFactories { get; set; } = [];

    internal List<InnerTrainingJobProfilerRuleConfigurationFactory> ProfilerRuleConfigurationsFactories { get; set; } = [];

    internal List<InnerTrainingJobDebugRuleConfigurationFactory> DebugRuleConfigurationsFactories { get; set; } = [];

    internal InnerTrainingJobDebugHookConfigFactory DebugHookConfigFactory { get; set; }

    internal InnerTrainingJobAlgorithmSpecificationFactory AlgorithmSpecificationFactory { get; set; }

    internal InnerTrainingJobOutputDataConfigFactory OutputDataConfigFactory { get; set; }

    internal InnerTrainingJobVpcConfigFactory VpcConfigFactory { get; set; }

    internal InnerTrainingJobCheckpointConfigFactory CheckpointConfigFactory { get; set; }

    internal InnerTrainingJobProfilerConfigFactory ProfilerConfigFactory { get; set; }

    internal InnerTrainingJobTensorBoardOutputConfigFactory TensorBoardOutputConfigFactory { get; set; }

    internal InnerTrainingJobInfraCheckConfigFactory InfraCheckConfigFactory { get; set; }

    internal InnerTrainingJobRemoteDebugConfigFactory RemoteDebugConfigFactory { get; set; }

    internal InnerTrainingJobStoppingConditionFactory StoppingConditionFactory { get; set; }

    internal InnerTrainingJobExperimentConfigFactory ExperimentConfigFactory { get; set; }

    internal InnerTrainingJobResourceConfigFactory ResourceConfigFactory { get; set; }

    internal InnerTrainingJobRetryStrategyFactory RetryStrategyFactory { get; set; }

    protected override Humidifier.SageMaker.TrainingJob Create()
    {
        var trainingJobResult = CreateTrainingJob();
        factoryAction?.Invoke(trainingJobResult);

        return trainingJobResult;
    }

    private Humidifier.SageMaker.TrainingJob CreateTrainingJob()
    {
        var trainingJobResult = new Humidifier.SageMaker.TrainingJob
        {
            GivenName = InputResourceName,
        };

        return trainingJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.TrainingJob result)
    {
        base.CreateChildren(result);

        result.InputDataConfig = InputDataConfigFactories.Any() ? InputDataConfigFactories.Select(x => x.Build()).ToList() : null;
        result.ProfilerRuleConfigurations = ProfilerRuleConfigurationsFactories.Any() ? ProfilerRuleConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.DebugRuleConfigurations = DebugRuleConfigurationsFactories.Any() ? DebugRuleConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.DebugHookConfig ??= DebugHookConfigFactory?.Build();
        result.AlgorithmSpecification ??= AlgorithmSpecificationFactory?.Build();
        result.OutputDataConfig ??= OutputDataConfigFactory?.Build();
        result.VpcConfig ??= VpcConfigFactory?.Build();
        result.CheckpointConfig ??= CheckpointConfigFactory?.Build();
        result.ProfilerConfig ??= ProfilerConfigFactory?.Build();
        result.TensorBoardOutputConfig ??= TensorBoardOutputConfigFactory?.Build();
        result.InfraCheckConfig ??= InfraCheckConfigFactory?.Build();
        result.RemoteDebugConfig ??= RemoteDebugConfigFactory?.Build();
        result.StoppingCondition ??= StoppingConditionFactory?.Build();
        result.ExperimentConfig ??= ExperimentConfigFactory?.Build();
        result.ResourceConfig ??= ResourceConfigFactory?.Build();
        result.RetryStrategy ??= RetryStrategyFactory?.Build();
    }

} // End Of Class

